'use strict';

/**
 * Per-session shell integration: generate the kit into a temporary directory,
 * hand back the environment to spawn with, and clean up on exit.
 *
 * Nothing is ever written to a user dotfile. Everything lives in a 0700
 * directory with an unpredictable name under the OS temp directory, every file
 * inside is 0600, and `dispose` removes the tree when the session ends.
 *
 * The generated files source the user's own configuration *first*, always. The
 * user's setup wins; Josh only appends to it.
 *
 * No Electron imports, for the same reason pty-manager.js keeps its binDir as
 * a plain string: this module has to be testable without booting an app.
 */

const fs = require('node:fs');
const path = require('node:path');
const { randomBytes } = require('node:crypto');

const KitThemes = require('../shared/kit-themes.js');
const KitPacks = require('../shared/kit-packs.js');
const KitEmit = require('../shared/kit-emit.js');

// themes.js lives under the renderer because that is where it was written,
// but it is a pure UMD data module with no DOM dependency beyond one function
// this file does not call. Requiring it here is what lets the prompt take its
// colours from the terminal's own active theme, which is the capability a
// shell framework structurally cannot have.
const Themes = require('../renderer/js/themes.js');

const DIR_MODE = 0o700;
const FILE_MODE = 0o600;

/**
 * Which dialect a resolved shell path speaks, or null for one the kit stays
 * out of. Windows PowerShell 5.1 is deliberately excluded: VT processing is
 * off by default there, so the prompt would render as visible escape codes.
 */
function dialectFor(shellPath) {
  if (typeof shellPath !== 'string' || shellPath === '') return null;
  const base = shellPath.split(/[\\/]/).pop().toLowerCase().replace(/\.exe$/, '');
  if (base === 'zsh') return 'zsh';
  if (base === 'bash') return 'bash';
  if (base === 'pwsh') return 'pwsh';
  return null;
}

/** A theme name from settings only ever selects a built-in; it is never a path. */
function themeFor(settings) {
  const wanted = settings && typeof settings.shellKitPrompt === 'string'
    ? settings.shellKitPrompt
    : '';
  return KitThemes.THEMES[wanted] || KitThemes.THEMES.classic;
}

/** The active colour theme's tables, so the prompt matches the terminal. */
function paletteFor(settings) {
  const name = settings && typeof settings.theme === 'string' ? settings.theme : '';
  const theme = Themes.THEMES[name]
    || Themes.THEMES[(settings && settings.darkTheme) || '']
    || Themes.THEMES['Tokyo Night'];
  return { ui: theme.ui, xterm: theme.xterm };
}

function packsFor(settings) {
  const wanted = settings && Array.isArray(settings.shellKitPacks) ? settings.shellKitPacks : [];
  return KitPacks.selectPacks(wanted);
}

function quote(value) {
  return KitEmit.quote(value, 'zsh');
}

/**
 * The glyph mode actually used.
 *
 * `shellKitGlyphs` is auto by default, which defers to what the renderer
 * measured against the real font. An explicit rich or plain overrides that,
 * because a user who has told Josh which one they want has better information
 * than a measurement.
 */
function glyphsFor(settings, detected) {
  const wanted = settings && typeof settings.shellKitGlyphs === 'string'
    ? settings.shellKitGlyphs
    : 'auto';
  if (wanted === 'rich' || wanted === 'plain') return wanted;
  return detected === 'rich' ? 'rich' : 'plain';
}

/** Every builder emits through this, so the three cannot drift apart. */
function emitOptions(context, dialect) {
  return KitEmit.emit(context.theme, context.packs, dialect, {
    glyphs: context.glyphs,
    ui: context.ui,
    xterm: context.xterm,
    gitUntracked: context.settings.shellKitGitUntracked !== false,
    gitSkip: context.settings.shellKitGitSkip,
    safeRemove: context.settings.shellKitSafeRemove === true,
  });
}

/**
 * zsh, and the subtlety that matters.
 *
 * Setting ZDOTDIR redirects *all four* startup files, not just .zshrc.
 * Forwarding only .zshrc silently loses the user's .zshenv and .zprofile --
 * which on macOS is where PATH usually comes from. So all of them are
 * generated, each sourcing its real counterpart first.
 *
 * .zshrc exports ZDOTDIR back to its real value once the kit is installed.
 * That is what stops every nested zsh re-running the integration, and it is
 * also why no .zlogin is generated: by the time zsh looks for one, ZDOTDIR
 * points at the user's directory again.
 */
function zshFiles(realZdotdir, kitPath) {
  const real = quote(realZdotdir);
  const header = '# Generated by Josh. Not a dotfile; deleted when this session ends.';

  const forward = (name) => [
    header,
    'JOSH_REAL_ZDOTDIR=' + real,
    'if [ -r "$JOSH_REAL_ZDOTDIR/' + name + '" ]; then',
    '  ZDOTDIR=$JOSH_REAL_ZDOTDIR',
    '  . "$JOSH_REAL_ZDOTDIR/' + name + '"',
    'fi',
  ];

  const kitDir = quote(path.dirname(kitPath));

  return {
    '.zshenv': forward('.zshenv').concat([
      '# A user .zshenv may set ZDOTDIR itself, so force it back to ours.',
      'ZDOTDIR=' + kitDir,
      '',
    ]).join('\n'),

    '.zprofile': forward('.zprofile').concat([
      'ZDOTDIR=' + kitDir,
      '',
    ]).join('\n'),

    '.zshrc': forward('.zshrc').concat([
      '',
      'if [ -r ' + quote(kitPath) + ' ]; then',
      '  . ' + quote(kitPath),
      'fi',
      '',
      '# Restore the real ZDOTDIR. This is what stops a nested zsh re-running',
      '# the integration, and what lets zsh find the user own .zlogin.',
      'export ZDOTDIR=$JOSH_REAL_ZDOTDIR',
      '',
    ]).join('\n'),
  };
}

/**
 * bash, and its honest caveat.
 *
 * --rcfile is ignored for login shells, and loginArgsFor in shell-resolver.js
 * starts POSIX shells with -l deliberately, because a non-login shell misses
 * /etc/paths and .zprofile and users report that their tools are missing. So
 * the kit rides an inherited PROMPT_COMMAND, which bash reads from the
 * environment and runs before the first prompt.
 *
 * The bootstrap removes itself once it has done its one job. It is written
 * with no glob metacharacter in it -- no star, question mark, bracket or
 * backslash -- so that the removal below can match it literally.
 *
 * A .bashrc that *assigns* PROMPT_COMMAND rather than appending to it wipes
 * the hook before it ever runs. Josh then does nothing at all, rather than
 * half-applying. That is exactly the case the optional export covers, so bash
 * is automatic in the common case and manual in the guaranteed one.
 */
const BASH_BOOTSTRAP = '. "$JOSH_KIT_FILE"';

function bashPreamble() {
  return [
    '# Generated by Josh. Not a dotfile; deleted when this session ends.',
    '#',
    '# Take the bootstrap back out of PROMPT_COMMAND, keeping whatever else is',
    '# in there. The pattern is quoted, so bash matches it as a literal string.',
    '__josh_boot=' + quote(BASH_BOOTSTRAP),
    'PROMPT_COMMAND=${PROMPT_COMMAND/"$__josh_boot"/}',
    "PROMPT_COMMAND=${PROMPT_COMMAND#'; '}",
    "PROMPT_COMMAND=${PROMPT_COMMAND%'; '}",
    "PROMPT_COMMAND=${PROMPT_COMMAND#';'}",
    'unset __josh_boot',
    '',
  ].join('\n');
}

const BUILDERS = {
  zsh(context) {
    const realZdotdir = context.env.ZDOTDIR || context.home;
    const kitPath = path.join(context.dir, 'josh-kit.zsh');

    const script = emitOptions(context, 'zsh');
    if (script === '') return null;

    const files = zshFiles(realZdotdir, kitPath);
    files['josh-kit.zsh'] = script;

    for (const name of Object.keys(files)) {
      fs.writeFileSync(path.join(context.dir, name), files[name], { mode: FILE_MODE });
    }

    return {
      env: { ZDOTDIR: context.dir, JOSH_REAL_ZDOTDIR: realZdotdir },
      args: [],
    };
  },

  bash(context) {
    const kitPath = path.join(context.dir, 'josh-kit.bash');

    const script = emitOptions(context, 'bash');
    if (script === '') return null;

    fs.writeFileSync(kitPath, bashPreamble() + script, { mode: FILE_MODE });

    return {
      env: { JOSH_KIT_FILE: kitPath, PROMPT_COMMAND: BASH_BOOTSTRAP },
      args: [],
    };
  },

  /**
   * PowerShell 7. Profiles load before -Command, so the user's profile wins
   * and Josh appends after it. -NoExit keeps the session interactive, which is
   * the whole point of a terminal.
   */
  pwsh(context) {
    const kitPath = path.join(context.dir, 'josh-kit.ps1');

    const script = emitOptions(context, 'pwsh');
    if (script === '') return null;

    fs.writeFileSync(kitPath, script, { mode: FILE_MODE });

    return {
      env: {},
      args: ['-NoExit', '-Command', '. ' + KitEmit.quote(kitPath, 'pwsh')],
    };
  },
};

/**
 * @param shell    the resolved shell path, as pty-manager already has it
 * @param settings the user's settings object
 * @param glyphs   'rich' | 'plain', as detected by the renderer
 * @param env      the environment the session will be spawned with
 * @param home     the user's home directory
 * @param tmpdir   the OS temp directory
 * @returns {{env: object, args: string[], dispose: function}|null}
 *
 * Returns null -- changing nothing at all -- when the kit must stay out of the
 * way. Half-applying is worse than not applying.
 */
function build({
  shell, settings = {}, glyphs = 'plain', env = {}, home = '', tmpdir = '', palette = null,
} = {}) {
  // Opt-in. An absent setting means the session starts exactly as it does
  // today, which is the only safe reading while the feature is new.
  if (settings.shellKit !== true) return null;

  // An explicit shellArgs is a choice the user made. Josh must not quietly
  // override it, so the kit stands down for the session.
  if (Array.isArray(settings.shellArgs) && settings.shellArgs.length > 0) return null;

  const dialect = dialectFor(shell);
  if (dialect === null) return null;

  const builder = BUILDERS[dialect];
  if (!builder) return null;

  let dir = null;
  try {
    dir = path.join(tmpdir, 'josh-kit-' + randomBytes(16).toString('hex'));
    fs.mkdirSync(dir, { mode: DIR_MODE, recursive: false });
  } catch {
    // A temp directory Josh cannot create is not an error worth failing a
    // terminal over. The session starts exactly as it does today.
    return null;
  }

  const dispose = () => {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
    } catch {
      // Best effort. The OS reclaims its own temp directory eventually, and a
      // failure here must never propagate into session teardown.
    }
  };

  const colours = palette && palette.ui && palette.xterm ? palette : paletteFor(settings);

  let built = null;
  try {
    built = builder({
      dir,
      env,
      home,
      settings,
      glyphs: glyphsFor(settings, glyphs),
      theme: themeFor(settings),
      packs: packsFor(settings),
      ui: colours.ui,
      xterm: colours.xterm,
    });
  } catch {
    built = null;
  }

  if (built === null) {
    dispose();
    return null;
  }

  return { env: built.env, args: built.args, dispose };
}

module.exports = {
  build, dialectFor, themeFor, packsFor, paletteFor, glyphsFor,
  DIR_MODE, FILE_MODE, BASH_BOOTSTRAP,
};
